#include <iostream>
#include <vector>
#include <string>
#include <unordered_set>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    unordered_set<long long> present(a.begin(), a.end());
    bool any = false;
    for (long long v = 1; v <= n; v++) {
        if (!present.count(v)) {
            if (any) cout << " ";
            cout << v;
            any = true;
        }
    }
    cout << (any ? "" : "none") << "\n";

    return 0;
}

